    ledgerIndex?: number;
    meta?: TransactionMetadata;
  }
}

function isFinalRejection(error: XrplError): boolean {
  return /Transaction failed, tem|greater than the transaction's LastLedgerSequence/.test(error.message);
}

function extractResultCode(message: string): string {
  return /\b(te[mcfl][A-Z_]+|tel[A-Z_]+)\b/.exec(message)?.[1] ?? 'EXPIRED';
}

