import type { Client, SubmittableTransaction, TransactionMetadata, TxResponse, Wallet } from 'xrpl';
import { XrplError } from 'xrpl';

import { TransactionFailedError, TransactionOutcomeUnknownError } from './errors.js';

export interface SubmittedTransaction {
  hash: string;
  ledgerIndex: number;
  resultCode: string;
  meta: TransactionMetadata;
}

/**
 * Signs and submits transactions for one account, waiting for each to be
 * validated. Submissions from the same instance are serialized so that
 * concurrent callers never race on the account's Sequence number.
 */
export class TransactionSubmitter {
  private queue: Promise<unknown> = Promise.resolve();

  constructor(
    private readonly client: Client,
    private readonly wallet: Wallet,
  ) {}

  get address(): string {
    return this.wallet.classicAddress;
  }

  /**
   * Submits `tx` and resolves once it is validated with `tesSUCCESS`.
   * @throws TransactionFailedError if validated with any other result, or rejected before inclusion.
   * @throws TransactionOutcomeUnknownError if submitted but the final outcome could not be determined.
   */
  submit<T extends SubmittableTransaction>(tx: T): Promise<SubmittedTransaction> {
    const run = this.queue.then(() => this.submitNow(tx));
    // Keep the queue alive regardless of this submission's outcome.
    this.queue = run.catch(() => undefined);
    return run;
  }

  /**
   * Like `submit`, but resolves with the result instead of throwing when the
   * ledger validates the transaction with a non-success code. Used to prove
   * that the ledger itself enforces a control.
   */
  async submitExpectingFailure<T extends SubmittableTransaction>(tx: T): Promise<SubmittedTransaction> {
    try {
      const ok = await this.submit(tx);
      return ok;
    } catch (error) {
      if (error instanceof TransactionFailedError && error.hash && error.ledgerIndex !== undefined && error.meta) {
        return { hash: error.hash, ledgerIndex: error.ledgerIndex, resultCode: error.resultCode, meta: error.meta };
      }
      throw error;
    }
  }

  private async submitNow<T extends SubmittableTransaction>(tx: T): Promise<SubmittedTransaction> {
    const prepared = await this.client.autofill({ ...tx, Account: this.wallet.classicAddress });
    const signed = this.wallet.sign(prepared);

    let response: TxResponse<T>;
    try {
      response = await this.client.submitAndWait<T>(signed.tx_blob);
    } catch (error) {
      // xrpl.js throws XrplError for `tem` rejections and for transactions that
      // expired (LastLedgerSequence passed without inclusion): both are final.
      if (error instanceof XrplError && isFinalRejection(error)) {
        throw new TransactionFailedError(tx.TransactionType, extractResultCode(error.message), signed.hash, error.message);
      }
      throw new TransactionOutcomeUnknownError(tx.TransactionType, signed.hash, prepared.LastLedgerSequence, {
        cause: error,
      });
    }

    const meta = response.result.meta;
    if (typeof meta !== 'object' || meta === null) {
      throw new TransactionOutcomeUnknownError(tx.TransactionType, signed.hash, prepared.LastLedgerSequence, {
        cause: new Error('Validated transaction has no metadata'),
      });
    }
    const resultCode = meta.TransactionResult;
    const ledgerIndex = response.result.ledger_index;
    if (ledgerIndex === undefined) throw new Error(`Validated transaction ${signed.hash} has no ledger_index`);

    if (resultCode !== 'tesSUCCESS') {
      throw Object.assign(new TransactionFailedError(tx.TransactionType, resultCode, signed.hash), {
        ledgerIndex,
        meta: meta as TransactionMetadata,
      });
    }
    return { hash: signed.hash, ledgerIndex, resultCode, meta: meta as TransactionMetadata };
  }
}

declare module './errors.js' {
  interface TransactionFailedError {
    /** Set when the failed transaction was validated in a ledger (tec codes). */
    ledgerIndex?: number;
    meta?: TransactionMetadata;
  }
}

function isFinalRejection(error: XrplError): boolean {
  return /Transaction failed, tem|greater than the transaction's LastLedgerSequence/.test(error.message);
}

function extractResultCode(message: string): string {
  return /\b(te[mcfl][A-Z_]+|tel[A-Z_]+)\b/.exec(message)?.[1] ?? 'EXPIRED';
}

